import os, pty, fcntl, termios, struct, select, time, json, pathlib, signal, sys
ROOT=pathlib.Path('/Users/chazu/dev/zig/birnam')
WORK=pathlib.Path(os.environ['LOGUE_PROBE_WORK']); WORK.mkdir(parents=True,exist_ok=True)
source=(ROOT/'examples/logue/logue.birnam').read_text().split('// ---- main ')[0]
source=source.replace('"../../wrapped/termbox2"',json.dumps(str(ROOT/'wrapped/termbox2'))).replace('"../../wrapped/termbox2/termbox2.birnam"',json.dumps(str(ROOT/'wrapped/termbox2/termbox2.birnam'))).replace('"logue-core.birnam"',json.dumps(str(ROOT/'examples/logue/logue-core.birnam')))
suffix='''
[Module load: #time]; [Module load: #json];
let measurements := [newCell value: #[]];
let measure := [:label :body |
 let chargeBefore := [[Execution wordResultOf: GC selector: #allocationBytes] asInteger];
 let cpu := [16 clockNanos]; let wall := [6 clockNanos];
 [body value];
 let elapsed := [[6 clockNanos] - wall]; let used := [[16 clockNanos] - cpu];
 [measurements set: [[measurements value] add: {"charge_before" -> chargeBefore "charge_after" -> [[Execution wordResultOf: GC selector: #allocationBytes] asInteger] "label" -> label "cpu_ns" -> used "wall_ns" -> elapsed "turn" -> [turn value] "monsters" -> [[monsters value] size]}]]];
[tb init]; [tb hideCursor];
[measure value: "new_game" value: [| [newGame value: #fighter]]];
[player set: [[[player value] at: #hp put: 100000] at: #maxHp put: 100000]];
[[1 to: 3] do: [:i |
 [measure value: "full_map" value: [| [drawFullMap value]]];
 [measure value: "entities" value: [| [drawEntities value]]];
 [measure value: "hud" value: [| [drawHud value]]];
 [measure value: "present" value: [| [tb present]]];
 [lastDepth set: [depth value]];
 [measure value: "dirty_draw" value: [| [draw value]]]]];
[[1 to: 3] do: [:i |
 [placeOn value: #down];
 [measure value: "descend_logic" value: [| [descend value]]];
 [measure value: "descend_draw" value: [| [draw value]]];
 [measure value: "ascend_logic" value: [| [ascend value]]];
 [measure value: "ascend_draw" value: [| [draw value]]]]];
[[1 to: 80] do: [:i |
 [measure value: "wait_logic" value: [| [endTurn value]]];
 [measure value: "wait_draw" value: [| [draw value]]]]];
[tb shutdown];
[System println: ["LOGUE_PROBE=" , [Json stringify: [measurements value]]]]
'''
name=sys.argv[1] if len(sys.argv)>1 else 'baseline'
if name=='flatglyph':
 start=source.index('let tileGlyph :='); end=source.index('let itemGlyph :=')
 source=source[:start]+'let tileGlyph := [:t | 46];\nlet tileColor := [:t | C_WHITE];\n'+source[end:]
if name=='noffi': source=source.replace('[tb setX: x y: y ch: ch fg: fg bg: 0]', 'nil')
if name=='identity':
 core=(ROOT/'examples/logue/logue-core.birnam').read_text().replace('let symEq := [:a :b | [[a printString] = [b printString]]];', 'let symEq := [:a :b | [a == b]];')
 corepath=WORK/'identity-core.birnam'; corepath.write_text(core)
 source=source.replace(str(ROOT/'examples/logue/logue-core.birnam'),str(corepath))
if name=='noauto': suffix=suffix.replace('[tb init];','[System gc]; [System autoGc: false]; [tb init];')
suffix=suffix.replace('[tb shutdown];', '[measure value: \"explicit_gc\" value: [| [System gc]]]; [tb shutdown];')
if name=='movement':
 suffix=suffix.split('[[1 to: 3] do:')[0]+'''[measure value: "initial_draw" value: [| [draw value]]];
 [[1 to: 240] do: [:i |
 [measure value: "move_logic" value: [| [act value: [[[i mod: 2] = 1] ifTrue: [| 108] ifFalse: [| 104]] value: 0]]];
 [measure value: "move_draw" value: [| [draw value]]]]];
 [tb shutdown];
 [System println: ["LOGUE_PROBE=" , [Json stringify: [measurements value]]]]
 '''
path=WORK/(name+'.birnam'); path.write_text(source+suffix)
pid,fd=pty.fork()
if pid==0:
 os.chdir(ROOT/'examples/logue'); os.environ['TERM']='xterm-256color'; os.environ['LC_ALL']='en_US.UTF-8'
 os.execv(os.environ['LOGUE_PROBE_BINARY'],['birnam',str(path)])
fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack('HHHH',32,100,0,0))
raw=bytearray(); end=time.monotonic()+180; status=None
while time.monotonic()<end:
 if select.select([fd],[],[],.05)[0]:
  try: data=os.read(fd,65536)
  except OSError: break
  if not data: break
  raw.extend(data)
 done,status=os.waitpid(pid,os.WNOHANG)
 if done: break
else:
 os.kill(pid,signal.SIGKILL); raise RuntimeError('timeout')
try: _,status=os.waitpid(pid,0)
except ChildProcessError: pass
(WORK/(name+'.raw')).write_bytes(raw)
s=raw.decode(errors='replace')
if 'LOGUE_PROBE=' not in s: print(s[-4000:]); raise SystemExit(1)
rows=json.JSONDecoder().raw_decode(s.split('LOGUE_PROBE=')[-1])[0]
(WORK/(name+'.json')).write_text(json.dumps(rows,indent=2))
import statistics
for label in dict.fromkeys(r['label'] for r in rows):
 vals=[r['wall_ns']/1e6 for r in rows if r['label']==label]
 print(label, 'n',len(vals),'median',round(statistics.median(vals),2),'max',round(max(vals),2))
print('status',status)

